// Parsear respuesta de Ollama
const ollamaResponse = $input.first().json.response || 
                       $input.first().json.output || 
                       $input.first().json.text ||
                       $input.first().json.content;

let analysis;

try {
  // Limpiar markdown
  let cleanResponse = ollamaResponse.trim()
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();

  // Extraer JSON
  const jsonMatch = cleanResponse.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    analysis = JSON.parse(cleanResponse);
  }

  // Validar estructura
  if (!analysis.puntuacion || !Array.isArray(analysis.aspectos_positivos)) {
    throw new Error('JSON inválido');
  }

} catch (error) {
  console.error('Error parsing:', error);

  // Fallback
  analysis = {
    puntuacion: 5,
    cumple_requisitos: false,
    aspectos_positivos: ["Código recibido correctamente"],
    errores_criticos: ["Error al analizar automáticamente el código"],
    sugerencias_mejora: ["Debe ser revisado manualmente por el profesor"],
    buenas_practicas: [],
    codigo_optimizado: "",
    comentarios_adicionales: "⚠️ Este análisis requiere revisión manual debido a un error técnico."
  };
}

// Obtener datos previos
const previousData = $('🔍 Extraer Datos').first().json;

// Calcular campos derivados
const aprobado = analysis.puntuacion >= 5;
const necesita_revision_manual = analysis.puntuacion < 3 || !analysis.cumple_requisitos;

// Retornar resultado combinado
return {
  json: {
    // Datos estudiante
    studentName: previousData.studentName,
    studentEmail: previousData.studentEmail,
    exerciseId: previousData.exerciseId,
    language: previousData.language,
    codeContent: previousData.codeContent,

    // Análisis IA
    puntuacion: analysis.puntuacion,
    cumple_requisitos: analysis.cumple_requisitos,
    aspectos_positivos: analysis.aspectos_positivos || [],
    errores_criticos: analysis.errores_criticos || [],
    sugerencias_mejora: analysis.sugerencias_mejora || [],
    buenas_practicas: analysis.buenas_practicas || [],
    codigo_optimizado: analysis.codigo_optimizado || "",
    comentarios_adicionales: analysis.comentarios_adicionales || "",

    // Campos calculados
    fecha_revision: new Date().toISOString(),
    aprobado: aprobado,
    necesita_revision_manual: necesita_revision_manual,
    estado: aprobado ? "APROBADO" : "NECESITA_REVISION"
  }
};

